const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{display:flex;flex-direction:column;min-width:0;min-height:0;overflow:hidden;color:var(--ink);font:12px/1.35 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.card *{box-sizing:border-box}\n.ib{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;gap:6px;padding:8px}\n.top{display:flex;align-items:center;gap:6px;min-width:0;flex:0 0 auto}\n.title{flex:1;min-width:0;font-weight:700;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.tabs{display:flex;gap:2px;padding:2px;border-radius:9px;background:var(--soft);flex:0 0 auto}\n.tab{border:0;background:transparent;color:var(--muted);font:inherit;font-weight:600;padding:4px 8px;border-radius:7px;cursor:pointer;white-space:nowrap}\n.tab.on{background:var(--accent);color:var(--on-accent)}\n.body{flex:1;min-width:0;min-height:0;overflow-y:auto;overflow-x:hidden;display:flex;flex-direction:column;gap:8px}\n.foot{display:flex;gap:6px;flex:0 0 auto}\n.btn{flex:1;min-width:0;min-height:30px;padding:5px 8px;border-radius:9px;border:1px solid var(--line);background:var(--button-paper,var(--panel-paper));color:var(--ink);font:inherit;font-weight:600;cursor:pointer}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.btn.sm{flex:0 0 auto;min-height:24px;padding:2px 8px;font-size:11px}\n.btn:disabled{opacity:.45;cursor:not-allowed}\n.btn:focus-visible,.tab:focus-visible,.chip:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.rcfg{display:flex;flex-direction:column;gap:6px;flex:0 0 auto;min-width:0}\n.rres{display:flex;flex-direction:column;gap:6px;min-width:0}\n.dates{display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:6px}\n.fld{display:flex;flex-direction:column;gap:2px;min-width:0;color:var(--muted);font-size:11px}\n.fld input,.fld textarea{width:100%;min-width:0;padding:4px 6px;border-radius:8px;border:1px solid var(--line);background:var(--panel-paper);color:var(--ink);font:inherit;font-size:12px}\n.fld textarea{resize:vertical;min-height:70px}\n.chips{display:flex;flex-wrap:wrap;gap:4px}\n.chip{border:1px solid var(--line);background:var(--panel-paper);color:var(--ink);font:inherit;font-size:11px;padding:2px 8px;border-radius:99px;cursor:pointer}\n.hint{margin:0;color:var(--muted);font-size:11px}\n.lead{margin:0;font-weight:600}\n.empty{display:flex;flex-direction:column;gap:6px;align-items:flex-start}\n.note{position:relative;display:flex;flex-direction:column;gap:2px;padding:6px 22px 6px 8px;border:1px solid var(--line);border-left:3px solid var(--accent-alt);border-radius:8px;background:var(--soft);font-size:11px}\n.note b{font-size:11px}\n.note .x{position:absolute;top:2px;right:2px;width:20px;height:20px;border:0;background:transparent;color:var(--muted);cursor:pointer;font-size:14px;line-height:1}\n.bar{display:flex;align-items:center;justify-content:space-between;gap:6px;flex-wrap:wrap}\n.acts{display:flex;gap:4px}\n.cnt{color:var(--muted);font-size:11px}\n.cands,.rev{display:flex;flex-direction:column;gap:6px;min-width:0}\n.list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:5px}\n.row{display:flex;align-items:flex-start;gap:6px;padding:6px;border:1px solid var(--line);border-radius:9px;background:var(--panel-paper);min-width:0}\n.row.on{border-color:var(--accent)}\n.row input[type=checkbox]{width:18px;height:18px;margin:1px 0 0;flex:0 0 auto;accent-color:var(--accent)}\n.main{flex:1;min-width:0}\n.subj{font-weight:600;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow-wrap:anywhere}\n.subj.full{-webkit-line-clamp:unset;display:block}\n.meta{color:var(--muted);font-size:11px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.meta.wrap{white-space:normal}\n.reason{color:var(--muted);font-size:11px;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow-wrap:anywhere}\n.tag{flex:0 0 auto;font-size:11px;color:var(--muted);padding:2px 6px;border:1px solid var(--line);border-radius:99px;white-space:nowrap}\n.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:6px}\n.stat{display:flex;flex-direction:column;align-items:center;padding:6px 2px;border-radius:9px;background:var(--soft)}\n.stat b{font-size:16px;line-height:1.1}\n.stat span{font-size:11px;color:var(--muted)}\n.sec h4{margin:0 0 4px;font-size:12px}\n@container card (max-width:260px){\n  .title{display:none}\n  .tabs{flex:1}\n  .tab{flex:1;padding:4px 2px}\n}\n@container card (min-width:380px){\n  .ib{padding:12px;gap:8px}\n  .card{font-size:13px}\n  .title{font-size:15px}\n  .btn.sm{min-height:26px;font-size:12px}\n}\n.card[data-size=\"6x3\"] .body.range{flex-direction:row;overflow:hidden}\n.card[data-size=\"6x3\"] .rcfg{flex:0 0 150px;overflow-y:auto}\n.card[data-size=\"6x3\"] .rres{flex:1;overflow-y:auto;min-height:0}\n.card[data-size=\"6x3\"] .dates{grid-template-columns:1fr 1fr}\n.card[data-size=\"6x3\"] .subj{-webkit-line-clamp:1}\n.card[data-size=\"6x6\"] .subj{-webkit-line-clamp:3}\n.card[data-size=\"6x6\"] .reason{-webkit-line-clamp:3}\n";
/* 整理收件箱：范围 -> 清单(可改理由/勾选) -> 确认 -> 结果/重试 */
function norm(s){
  s=s&&typeof s==='object'?s:{};
  const r=s.range&&typeof s.range==='object'?s.range:{};
  return {range:{from:String(r.from||''),to:String(r.to||'')},plan:Array.isArray(s.plan)?s.plan:[]};
}
function pad2(n){return (n<10?'0':'')+n;}
function fmtDay(d){return d.getFullYear()+'-'+pad2(d.getMonth()+1)+'-'+pad2(d.getDate());}
function daysAgo(n){const d=new Date();d.setDate(d.getDate()-n);return fmtDay(d);}
function toDay(v){
  if(v===''||v===null||v===undefined)return '';
  if(typeof v==='number'){const d=new Date(v<1e12?v*1000:v);return isNaN(d.getTime())?'':fmtDay(d);}
  const t=String(v);
  if(/^\d{4}-\d{2}-\d{2}$/.test(t))return t;
  const d=new Date(t);
  if(!isNaN(d.getTime()))return fmtDay(d);
  return /^\d{4}-\d{2}-\d{2}/.test(t)?t.slice(0,10):'';
}
function pick(o,keys){
  for(let i=0;i<keys.length;i++){const v=o[keys[i]];if(v!==undefined&&v!==null&&v!=='')return v;}
  return '';
}
function personText(v){
  if(v&&typeof v==='object'){return String(v.name||v.address||v.email||'');}
  return String(v||'');
}
function listOf(d){
  if(Array.isArray(d))return d;
  if(d&&typeof d==='object'){
    const ks=['messages','items','list','results','data'];
    for(let i=0;i<ks.length;i++){if(Array.isArray(d[ks[i]]))return d[ks[i]];}
  }
  return null;
}
function normMail(o){
  if(!o||typeof o!=='object')return null;
  const id=pick(o,['id','messageId','message_id','mid','uid']);
  if(id==='')return null;
  return {
    id:String(id),
    subject:String(pick(o,['subject','title','summary'])),
    from:personText(pick(o,['from','sender','fromName','from_name','from_address'])),
    day:toDay(pick(o,['date','receivedAt','received_at','receivedDate','internalDate','time','timestamp','sentAt','sent_at']))
  };
}
function explainError(e){
  const t=String((e&&(e.code||e.errorCode))||'')+' '+String((e&&e.message)||e||'');
  if(/permission|denied|binding|not_bound|unauthor/i.test(t))return '邮箱尚未连接：需要先在平台为这张卡片连接邮箱，才能读取邮件。';
  if(/format/i.test(t))return '读到了数据，但邮件格式无法识别，没有可用邮件。';
  return '读取邮件失败：'+((e&&e.message)?e.message:'未知错误')+'。可再次点击“读取邮件”重试。';
}

function mount(ctx){
  const {root,el,state,ui,update,redraw,host,uid,day}=ctx;
  const s=norm(state);
  const today=day();
  ui.jobs=ui.jobs||{};
  ui.scroll=ui.scroll||{};
  ui.step=ui.step||'range';

  const h=(tag,attrs,...kids)=>el(tag,attrs||{},...kids.flat(2).filter(x=>x!==null&&x!==undefined&&x!==false));
  const btn=(label,onclick,o)=>{
    o=o||{};
    return h('button',{type:'button',class:'btn'+(o.primary?' primary':'')+(o.sm?' sm':''),disabled:!!o.disabled,onclick:onclick},label);
  };
  const fail=e=>{ui.notice={where:ui.confirm?'confirm':ui.step,text:'保存失败：'+((e&&e.message)?e.message:'未知错误')};redraw();};
  const go=step=>{ui.step=step;ui.notice=null;ui.editId=null;ui.draft=null;ui.confirm=false;redraw();};
  const setRange=patch=>{
    update(cur=>{const n=norm(cur);return Object.assign({},cur,{range:Object.assign({},n.range,patch),plan:n.plan});}).catch(fail);
  };
  const mutatePlan=fn=>update(cur=>{const n=norm(cur);return Object.assign({},cur,{range:n.range,plan:fn(n.plan)});});
  const makeItem=m=>({id:uid(),mailId:m.id,subject:m.subject,from:m.from,day:m.day,reason:'',checked:true});
  const addMails=list=>{
    mutatePlan(plan=>{
      const have={};plan.forEach(p=>{have[p.mailId]=1;});
      const add=list.filter(m=>!have[m.id]).map(makeItem);
      return plan.concat(add);
    }).catch(fail);
  };
  // 邮件读取：只读数据源，必须由平台为本卡片建立邮箱绑定
  const runJob=async(key,fn)=>{
    if(ui.jobs[key]&&ui.jobs[key].status==='loading')return false;
    ui.jobs[key]={status:'loading'};redraw();
    try{
      const data=await fn();
      ui.jobs[key]={status:'ok',data:data};redraw();return true;
    }catch(e){
      ui.jobs[key]={status:'error',error:explainError(e)};redraw();return false;
    }
  };
  const loadMails=async()=>{
    const r=await host.fetchData('connected.mail.message-list');
    if(!r||r.status!=='ok'){const e=new Error((r&&(r.errorCode||r.status))||'no_response');e.code=e.message;throw e;}
    const arr=listOf(r.data);
    if(!arr)throw new Error('format');
    const mails=[];let skipped=0;
    arr.forEach(o=>{const m=normMail(o);if(m)mails.push(m);else skipped++;});
    if(arr.length&&!mails.length)throw new Error('format');
    return {mails:mails,skipped:skipped};
  };
  const noAi=()=>{
    ui.notice={where:'range',text:'AI 建议未接入：平台目前没有 AI 推理接口，无法自动判断哪些邮件该归档。你的日期范围已保存；可先读取邮件，再手动加入清单并写下理由。'};
    redraw();
  };
  const noArchive=()=>{
    ui.notice={where:ui.step==='result'?'result':'confirm',text:'邮件归档未接入：平台目前没有归档接口，本次没有归档任何邮件，也没有成功或失败记录。你的勾选和理由都已保存。'};
    redraw();
  };
  const note=(label,text)=>h('div',{class:'note',role:'status'},h('b',{},label),h('span',{},text));
  const noticeFor=where=>ui.notice&&ui.notice.where===where?
    h('div',{class:'note',role:'status'},h('b',{},'提示'),h('span',{},ui.notice.text),
      h('button',{type:'button',class:'x','aria-label':'关闭提示',onclick:()=>{ui.notice=null;redraw();}},'×')):null;

  // ---------- 步骤 1：范围 ----------
  function renderRange(){
    const r=s.range;
    const bad=!r.from||!r.to||r.from>r.to;
    const job=ui.jobs.mails;
    const inPlan={};s.plan.forEach(p=>{inPlan[p.mailId]=1;});
    const dateBox=(label,key)=>h('label',{class:'fld'},h('span',{},label),
      h('input',{type:'date',value:r[key],'aria-label':label+'日期',onchange:e=>{const p={};p[key]=e.target.value;setRange(p);}}));
    const cfg=h('div',{class:'rcfg'},
      h('div',{class:'dates'},dateBox('开始','from'),dateBox('结束','to')),
      h('div',{class:'chips'},[[7,'近7天'],[30,'近30天'],[90,'近90天']].map(p=>
        h('button',{type:'button',class:'chip',onclick:()=>setRange({from:daysAgo(p[0]-1),to:today})},p[1]))),
      !r.from||!r.to?h('p',{class:'hint'},'先选开始和结束日期。'):(r.from>r.to?h('p',{class:'hint'},'开始日期不能晚于结束日期。'):null)
    );
    let res;
    if(!job){
      res=h('p',{class:'hint'},'选好范围后点“读取邮件”。AI 建议目前未接入，可手动挑选邮件加入清单。');
    }else if(job.status==='loading'){
      res=h('p',{class:'hint'},'正在读取邮件…');
    }else if(job.status==='error'){
      res=note('读取失败',job.error);
    }else{
      const all=job.data.mails;
      const list=bad?[]:all.filter(m=>m.day&&m.day>=r.from&&m.day<=r.to);
      const fresh=list.filter(m=>!inPlan[m.id]);
      res=h('div',{class:'cands'},
        h('div',{class:'bar'},h('span',{class:'cnt'},'范围内 '+list.length+' 封 / 共读取 '+all.length+' 封'),
          fresh.length?btn('全部加入('+fresh.length+')',()=>addMails(fresh),{sm:true}):null),
        job.data.skipped?h('p',{class:'hint'},job.data.skipped+' 封缺少编号，无法处理，未列出。'):null,
        list.length?h('ul',{class:'list'},list.map(m=>h('li',{class:'row'},
          h('div',{class:'main'},h('div',{class:'subj'},m.subject||'（无主题）'),
            h('div',{class:'meta'},(m.from||'未知发件人')+' · '+m.day.slice(5))),
          inPlan[m.id]?h('span',{class:'tag'},'已加入'):btn('加入',()=>addMails([m]),{sm:true})))):
          h('p',{class:'hint'},bad?'日期范围有误，无法筛选。':'这个日期范围内没有邮件。')
      );
    }
    const body=h('div',{class:'body range',onscroll:e=>{ui.scroll.range=e.target.scrollTop;}},
      cfg,h('div',{class:'rres'},noticeFor('range'),res));
    const foot=h('div',{class:'foot'},
      btn('AI 建议',noAi),
      btn(job&&job.status==='loading'?'读取中…':'读取邮件',()=>runJob('mails',loadMails),{primary:true,disabled:bad||(job&&job.status==='loading')}));
    return [body,foot];
  }


  // ---------- 步骤 2：清单（改理由、勾选、确认） ----------
  const checkedItems=()=>s.plan.filter(p=>p.checked);
  const sub=p=>(p.from||'未知发件人')+(p.day?' · '+p.day.slice(5):'');

  function renderEdit(item){
    const cur=ui.draft!==null&&ui.draft!==undefined?ui.draft:(item.reason||'');
    const save=()=>{
      mutatePlan(plan=>plan.map(p=>p.id===item.id?Object.assign({},p,{reason:String(ui.draft!==null&&ui.draft!==undefined?ui.draft:(p.reason||'')).trim()}):p))
        .then(()=>{ui.editId=null;ui.draft=null;redraw();}).catch(fail);
    };
    const remove=()=>{
      mutatePlan(plan=>plan.filter(p=>p.id!==item.id)).then(()=>{ui.editId=null;ui.draft=null;redraw();}).catch(fail);
    };
    const body=h('div',{class:'body'},
      noticeFor('review'),
      h('div',{class:'subj full'},item.subject||'（无主题）'),
      h('div',{class:'meta wrap'},sub(item)),
      h('label',{class:'fld'},h('span',{},'归档理由（可修改）'),
        h('textarea',{rows:4,value:cur,placeholder:'为什么建议归档这封邮件？',oninput:e=>{ui.draft=e.target.value;}})),
      btn('移出清单',remove,{sm:true}));
    const foot=h('div',{class:'foot'},
      btn('返回',()=>{ui.editId=null;ui.draft=null;redraw();}),
      btn('保存',save,{primary:true}));
    return [body,foot];
  }

  function renderConfirm(){
    const items=checkedItems();
    const body=h('div',{class:'body'},
      h('p',{class:'lead'},'将归档 '+items.length+' 封邮件，范围 '+(s.range.from||'?')+' 至 '+(s.range.to||'?')+'。请确认。'),
      noticeFor('confirm'),
      h('ul',{class:'list'},items.map(p=>h('li',{class:'row'},
        h('div',{class:'main'},h('div',{class:'subj'},p.subject||'（无主题）'),
          h('div',{class:'reason'},p.reason||'未写理由'))))));
    const foot=h('div',{class:'foot'},
      btn('返回修改',()=>{ui.confirm=false;ui.notice=null;redraw();}),
      btn('确认归档',noArchive,{primary:true,disabled:!items.length}));
    return [body,foot];
  }

  function renderReview(){
    if(ui.editId){
      const it=s.plan.find(p=>p.id===ui.editId);
      if(it)return renderEdit(it);
      ui.editId=null;
    }
    if(ui.confirm&&checkedItems().length)return renderConfirm();
    ui.confirm=false;
    const plan=s.plan;
    const n=checkedItems().length;
    const setAll=v=>mutatePlan(list=>list.map(p=>Object.assign({},p,{checked:v}))).catch(fail);
    const toggle=(id,v)=>mutatePlan(list=>list.map(p=>p.id===id?Object.assign({},p,{checked:v}):p)).catch(fail);
    let content;
    if(!plan.length){
      content=h('div',{class:'empty'},
        h('p',{class:'lead'},'清单还是空的。'),
        h('p',{class:'hint'},'AI 建议目前未接入，不会自动列出邮件。请到“范围”读取邮件，再手动加入清单。'),
        btn('去选范围',()=>go('range'),{sm:true}));
    }else{
      content=h('div',{class:'rev'},
        h('div',{class:'bar'},h('span',{class:'cnt'},'已勾选 '+n+' / '+plan.length),
          h('span',{class:'acts'},btn('全选',()=>setAll(true),{sm:true}),btn('清除',()=>setAll(false),{sm:true}))),
        h('ul',{class:'list'},plan.map(p=>h('li',{class:'row'+(p.checked?' on':'')},
          h('input',{type:'checkbox',checked:!!p.checked,'aria-label':'选择：'+(p.subject||'无主题'),onchange:e=>toggle(p.id,e.target.checked)}),
          h('div',{class:'main'},h('div',{class:'subj'},p.subject||'（无主题）'),
            h('div',{class:'meta'},sub(p)),
            h('div',{class:'reason'},p.reason?('理由：'+p.reason):'未写理由，点“改”补充')),
          btn('改',()=>{ui.editId=p.id;ui.draft=null;redraw();},{sm:true,aria:'修改理由'})))));
    }
    const body=h('div',{class:'body',onscroll:e=>{ui.scroll.review=e.target.scrollTop;}},noticeFor('review'),content);
    const foot=h('div',{class:'foot'},
      btn('确认归档（'+n+'）',()=>{ui.confirm=true;ui.notice=null;redraw();},{primary:true,disabled:!n}));
    return [body,foot];
  }


  // ---------- 步骤 3：结果与重试 ----------
  function renderResult(){
    const plan=s.plan;
    const okList=plan.filter(p=>p.status==='ok');
    const badList=plan.filter(p=>p.status==='failed');
    const waitList=plan.filter(p=>p.status!=='ok'&&p.status!=='failed');
    const stat=(label,n)=>h('div',{class:'stat'},h('b',{},String(n)),h('span',{},label));
    const retry=ids=>noArchive(ids);
    const item=(p,extra)=>h('li',{class:'row'},
      h('div',{class:'main'},h('div',{class:'subj'},p.subject||'（无主题）'),
        h('div',{class:'meta wrap'},p.error?('原因：'+p.error):sub(p))),extra||null);
    const body=h('div',{class:'body',onscroll:e=>{ui.scroll.result=e.target.scrollTop;}},
      h('div',{class:'stats'},stat('成功',okList.length),stat('失败',badList.length),stat('未处理',waitList.length)),
      note('未接入','邮件归档目前未接入，不会执行归档，所以还没有成功或失败的结果。接入后，这里会列出每封邮件的结果，失败的可单独重试。'),
      noticeFor('result'),
      h('div',{class:'sec'},h('h4',{},'成功 '+okList.length),
        okList.length?h('ul',{class:'list'},okList.map(p=>item(p))):h('p',{class:'hint'},'暂无')),
      h('div',{class:'sec'},h('h4',{},'失败 '+badList.length),
        badList.length?h('ul',{class:'list'},badList.map(p=>item(p,btn('重试',()=>retry([p.id]),{sm:true})))):h('p',{class:'hint'},'暂无')));
    const foot=badList.length>1?h('div',{class:'foot'},btn('重试全部失败项（'+badList.length+'）',()=>retry(badList.map(p=>p.id)),{primary:true})):null;
    return [body,foot];
  }

